    elif arg.startswith('-') and len(arg) > 1:
        j = 1
        while j < len(arg):
            c = arg[j]
            if c in '0123456789':
                if c == '1' and j+1 < len(arg) and arg[j+1] == '1':
                    options['level'] = 9 # missing Zopfli
                    j += 2
                else:
                    options['level'] = int(c)
                    j += 1
