    elif arg.startswith('--') and len(arg) > 2:
        if arg == '--fast': options['level'] = 1
        elif arg == '--best': options['level'] = 9
        elif arg == '--alias': i+=1; options['alias'] = args[i]
        elif arg.startswith('--alias='): options['alias'] = arg.split('=', 1)[1]
        elif arg == '--blocksize': i+=1; options['blocksize'] = int(args[i])
        elif arg == '--stdout': options['stdout'] = True
        elif arg == '--comment': i+=1; options['comment'] = args[i]
        elif arg.startswith('--comment='): options['comment'] = arg.split('=', 1)[1]
        elif arg == '--decompress': options['decompress'] = True
        elif arg == '--force': options['force'] = True
        elif arg == '--first': options['first'] = True
        elif arg == '--help': options['help'] = True
        elif arg == '--huffman': options['huffman'] = True
        elif arg == '--independent': options['independent'] = True
        elif arg == '--iterations': i+=1; options['iterations'] = int(args[i])
        elif arg == '--maxsplits': i+=1; options['maxsplits'] = int(args[i])
        elif arg == '--keep': options['keep'] = True
        elif arg == '--zip': options['zip'] = True
        elif arg == '--list': options['list'] = True
        elif arg == '--license': options['license'] = True
        elif arg == '--no-time': options['no_time'] = True
        elif arg == '--time': options['time'] = True
        elif arg == '--no-name': options['no_name'] = True
        elif arg == '--name': options['name'] = True
        elif arg == '--oneblock': options['oneblock'] = True
        elif arg == '--processes': i+=1; options['processes'] = int(args[i])
        elif arg == '--quiet': options['quiet'] = True
        elif arg == '--recursive': options['recursive'] = True
        elif arg == '--rsyncable': options['rsyncable'] = True
        elif arg == '--suffix': i+=1; options['suffix'] = args[i]
        elif arg.startswith('--suffix='): options['suffix'] = arg.split('=', 1)[1]
        elif arg == '--test': options['test'] = True
        elif arg == '--rle': options['rle'] = True
        elif arg == '--verbose': options['verbose'] = True
        elif arg == '--version': options['version'] = True
        elif arg == '--synchronous': options['synchronous'] = True
        elif arg == '--zlib': options['zlib'] = True
        else: abort(f"invalid option: {arg}")
    elif arg.startswith('-') and len(arg) > 1:
        j = 1
        while j < len(arg):
            c = arg[j]
            if c in '0123456789':
                if c == '1' and j+1 < len(arg) and arg[j+1] == '1':
                    options['level'] = 9
                    j += 2
                else:
                    options['level'] = int(c)
                    j += 1
            elif c in 'pbIAJS':
                rem = arg[j+1:]
                if rem: val = rem; j = len(arg)
                else:
                    i += 1
                    if i >= len(args): abort(f"missing argument for -{c}")
                    val = args[i]
                    j += 1
                if c == 'p': options['processes'] = int(val)
                elif c == 'b': options['blocksize'] = int(val)
                elif c == 'I': options['iterations'] = int(val)
                elif c == 'A': options['alias'] = val
                elif c == 'J': options['maxsplits'] = int(val)
                elif c == 'S': options['suffix'] = val
            elif c == 'C':
                rem = arg[j+1:]
                if rem: val = rem; j = len(arg)
                else:
                    i += 1
                    if i >= len(args): abort("missing argument for -C")
                    val = args[i]
                    j += 1
                options['comment'] = val
            else:
                mapping = {'c': 'stdout', 'd': 'decompress', 'f': 'force', 'F': 'first',
                           'h': 'help', 'H': 'huffman', 'i': 'independent', 'k': 'keep',
                           'K': 'zip', 'l': 'list', 'L': 'license', 'm': 'no_time', 'M': 'time',
