                           'r': 'recursive', 'R': 'rsyncable', 't': 'test', 'U': 'rle',
                           'v': 'verbose', 'V': 'version', 'Y': 'synchronous', 'z': 'zlib'}
                if c in mapping:
                    options[mapping[c]] = True
                    j += 1
                else:
                    abort(f"invalid option: -{c}")
    else:
        files.append(arg)
    i += 1

