def list_file(path):
    if path == '-': return
    try:
        compressed = os.path.getsize(path)
        with open(path, 'rb') as f:
            f.seek(-4, os.SEEK_END)
            original = struct.unpack('<I', f.read(4))[0]
        reduced = f"{(1 - compressed/original)*100:.1f}%" if original else "0.0%"
        print(f"{compressed:>10} {original:>10} {reduced:>8}  {os.path.basename(path)[:-3] if path.endswith('.gz') else os.path.basename(path)}")
    except: pass

def process_single(in_path):
    if options['list']:
        list_file(in_path)
        return
    is_stdin = (in_path == '-')
    if not is_stdin and not os.path.exists(in_path):
        if not options['quiet']: skip(f"{in_path} does not exist")
        return

    out_path = None
    if options['decompress'] or options['test']:
        if is_stdin:
            out_path = '-'
        else:
            if not in_path.endswith(options['suffix']) and not in_path.endswith('.zip') and not in_path.endswith('.zz') and not in_path.endswith('.gz'):
                if not options['quiet']: skip(f"{in_path} does not have compressed suffix")
                return
            out_path = in_path[:-len(options['suffix'])] if in_path.endswith(options['suffix']) else (in_path[:-3] if in_path.endswith('.gz') else in_path + '.out')
        if options['stdout'] or options['test']: out_path = '-'
        if out_path != '-' and os.path.exists(out_path) and not options['force']:
            if not options['quiet']: skip(f"{out_path} exists")
            return
        in_f = sys.stdin.buffer if is_stdin else open(in_path, 'rb')
        out_f = sys.stdout.buffer if out_path == '-' else open(out_path, 'wb')
        try:
            if options['test']: out_f = open(os.devnull, 'wb')
            d = zlib.decompressobj(wbits=47)
            while True:
                chunk = in_f.read(128 * 1024)
                if not chunk: break
                out = d.decompress(chunk)
                if out: out_f.write(out)
                while d.unused_data:
                    unused = d.unused_data
                    d = zlib.decompressobj(wbits=47)
                    out = d.decompress(unused)
                    if out: out_f.write(out)
            if not is_stdin: in_f.close()
            if out_path != '-' and not options['test']: out_f.close()
            if not is_stdin and not options['stdout'] and not options['keep'] and not options['test']: os.remove(in_path)
        except Exception as e:
            if not options['quiet']: abort(str(e))
    else:
        if is_stdin:
            out_path = '-'
        else:
            out_path = in_path + options['suffix']
            if options['zip']: out_path = in_path + '.zip'
            if options['zlib']: out_path = in_path + '.zz'
        if options['stdout']: out_path = '-'

        if out_path != '-' and os.path.exists(out_path) and not options['force']:
            if not options['quiet']: skip(f"{out_path} exists")
            return
        in_f = sys.stdin.buffer if is_stdin else open(in_path, 'rb')
        out_f = sys.stdout.buffer if out_path == '-' else open(out_path, 'wb')
        try:
            mtime = time.time() if is_stdin else os.path.getmtime(in_path)
            filename = "" if is_stdin else os.path.basename(in_path)
            if options['zip']:
                with zipfile.ZipFile(out_f, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
                    zinfo = zipfile.ZipInfo(filename or '-', time.localtime(mtime)[:6])
                    zinfo.compress_type = zipfile.ZIP_DEFLATED
                    while True:
                        chunk = in_f.read(128*1024)
                        if not chunk: break
                        zf.writestr(zinfo, chunk, compress_type=zipfile.ZIP_DEFLATED, compresslevel=options['level'])
            elif options['zlib']:
                CMF = 0x78
                FLG = 1 << 6
                FLG += 31 - ((CMF * 256 + FLG) % 31)
                out_f.write(bytearray([CMF, FLG]))
                crc = 0
                def comp_chunk(chunk): return zlib.compressobj(level=options['level'], method=zlib.DEFLATED, wbits=-15).compress(chunk) + zlib.compressobj(level=options['level'], method=zlib.DEFLATED, wbits=-15).flush(zlib.Z_SYNC_FLUSH)
                from collections import deque
                futures = deque()
                with concurrent.futures.ThreadPoolExecutor(max_workers=options['processes']) as ex:
                    while True:
                        chunk = in_f.read(options['blocksize'] * 1024)
                        if not chunk: break
                        crc = zlib.adler32(chunk, crc) & 0xFFFFFFFF
                        if len(futures) >= options['processes'] * 2: out_f.write(futures.popleft().result())
                        futures.append(ex.submit(comp_chunk, chunk))
                    while futures: out_f.write(futures.popleft().result())
                c = zlib.compressobj(level=options['level'], method=zlib.DEFLATED, wbits=-15)
                out_f.write(c.flush())
                out_f.write(struct.pack('>I', crc))
            else:
                flags = 0x08 if (not options['no_name'] and filename) else 0
                header = bytearray(b'\x1f\x8b\x08')
                header.append(flags)
                header.extend(struct.pack('<I', int(mtime) if not options['no_time'] else 0))
                header.append(2 if options['level'] >= 9 else (4 if options['level'] == 1 else 0))
                header.append(3)
                if flags & 0x08: header.extend(filename.encode('utf-8') + b'\x00')
                out_f.write(header)
                crc = 0; size = 0
                prev_chunk = b""
                def comp_chunk(chunk, zdict):
                    c = zlib.compressobj(level=options['level'], method=zlib.DEFLATED, wbits=-15, memLevel=8, strategy=zlib.Z_DEFAULT_STRATEGY, zdict=zdict) if zdict else zlib.compressobj(level=options['level'], method=zlib.DEFLATED, wbits=-15, memLevel=8, strategy=zlib.Z_DEFAULT_STRATEGY)
                    return c.compress(chunk) + c.flush(zlib.Z_SYNC_FLUSH)
                from collections import deque
                futures = deque()
                with concurrent.futures.ThreadPoolExecutor(max_workers=options['processes']) as ex:
                    while True:
                        chunk = in_f.read(options['blocksize'] * 1024)
                        if not chunk: break
                        crc = binascii.crc32(chunk, crc) & 0xFFFFFFFF
                        size = (size + len(chunk)) & 0xFFFFFFFF
                        zdict = prev_chunk[-32768:] if prev_chunk and not options['independent'] else None
                        if len(futures) >= options['processes'] * 2: out_f.write(futures.popleft().result())
                        futures.append(ex.submit(comp_chunk, chunk, zdict))
                        prev_chunk = chunk
                    while futures: out_f.write(futures.popleft().result())
                c = zlib.compressobj(level=options['level'], method=zlib.DEFLATED, wbits=-15)
                out_f.write(c.flush())
                out_f.write(struct.pack('<II', crc, size))
            if not is_stdin: in_f.close()
            if out_path != '-': out_f.close()
            if not is_stdin and not options['stdout'] and not options['keep']: os.remove(in_path)
        except Exception as e:
            if not options['quiet']: abort(str(e))

for f in files:
    if os.path.isdir(f) and options['recursive']:
        for root, dirs, fnames in os.walk(f):
            for fname in fnames: process_single(os.path.join(root, fname))
    elif os.path.isdir(f):
        if not options['quiet']: skip(f"{f} is a directory")
    else: process_single(f)
